  'Showing {shown} of {total} sessions': ['显示 {total} 个会话中的 {shown} 个', '{total} 件中 {shown} 件を表示', 'Mostrando {shown} de {total} sesiones', 'Показано {shown} из {total} сеансов'],
  'No sessions match. Change the search or filter.': ['没有匹配的会话。请更改搜索或筛选条件。', '一致するセッションがありません。検索またはフィルターを変更してください。', 'No hay sesiones coincidentes. Cambia la búsqueda o el filtro.', 'Совпадений нет. Измените поиск или фильтр.'],
  'Show more': ['显示更多', 'さらに表示', 'Mostrar más', 'Показать ещё'],
